KG42.register("rules-980432ecada687a4896605a3",{"id":"35-microgrid_pool_strategy::v141-c-R003","paper":"35-microgrid_pool_strategy","record":{"rule_id":"v141-c-R003","mechanism_id":"v141-a-M01","name":"Supply submission","process_stage":"bidding","market_meaning":"Price-signal coordination provides DLMP feedback to MG supply-offer decisions. Scope: Price-maker MG supply-offer decisions in the decentralized distribution electricity market. A microgrid may submit supply offers when it exports power to the DS. Scope: Microgrid supply-offer submission in the distribution electricity market. Condition: The microgrid exports power to the DS.","independence_rationale":"Relations governed by the approved function bidding.supply under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["bidding.supply","coordination.price_signal"],"E":[{"edge_id":"v141-c-R003-E001","source":"coordination.price_signal","target":"bidding.supply","type":"links","constraint_ids":["v141-c-R003-C001"],"evidence_ids":["v141-b-g01-E06","v141-b-g01-E08"]}],"omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"bidding","context_text":"Microgrid supply-offer submission in the distribution electricity market. | Price-maker MG supply-offer decisions in the decentralized distribution electricity market.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E06","v141-b-g01-E08","v141-b-g02-E26"]},"x":[{"variable_id":"v141-c-R003-x-alpha-prime-jt","symbol":"\\alpha'_{jt}","meaning":"Modified MG j bid/offer price; in this rule it is the supply-offer price when the MG exports power to the DS.","kind":"operational","domain":"real-valued price; the source gives no explicit numeric bounds for the offer strategy","unit":"$/p.u.","indices":["j","t"],"evidence_ids":["v141-b-g02-E28","v141-b-g02-E30","v141-b-g02-E31"]},{"variable_id":"v141-c-R003-x-P-jt","symbol":"P_{jt}","meaning":"MG j real-power exchange with the DS in time t; positive values denote export to the DS and negative values denote extraction from the DS as used by the source's offer strategy.","kind":"operational","domain":"real-valued power exchange with positive export and negative extraction","unit":"p.u.","indices":["j","t"],"evidence_ids":["v141-b-g02-E30","v141-b-g02-E31","v141-b-g02-E41"]}],"theta":[{"parameter_id":"v141-c-R003-theta-Pmax-j","symbol":"P_j^{\\max}","meaning":"Maximum real-power exchange capacity of MG j at the PCC.","value":{"kind":"symbolic","number_value":null,"text_value":"upper exchange-capacity limit; numeric value not specified in this rule"},"unit":"p.u.","indices":["j"],"evidence_ids":["v141-b-g02-E28","v141-b-g02-E30","v141-b-g02-E31"]},{"parameter_id":"v141-c-R003-theta-beta-jt","symbol":"\\beta_{jt}","meaning":"MG j marginal operation cost in time t, supplied as price information to the modified offer strategy.","value":{"kind":"symbolic","number_value":null,"text_value":"given marginal-cost information; numeric value not specified in this rule"},"unit":"$/p.u.","indices":["j","t"],"evidence_ids":["v141-b-g01-E03","v141-b-g02-E28","v141-b-g02-E30","v141-b-g02-E31"]},{"parameter_id":"v141-c-R003-theta-lambda-P-bt","symbol":"\\lambda^{P}_{bt}","meaning":"Distribution locational marginal price (DLMP) at node b in time t, used as the price-signal input to the MG supply-offer rule.","value":{"kind":"symbolic","number_value":null,"text_value":"DLMP price signal from DEM clearing; numeric value not specified in this rule"},"unit":"$/p.u.","indices":["b","t"],"evidence_ids":["v141-b-g01-E03","v141-b-g01-E06","v141-b-g01-E08","v141-b-g02-E15","v141-b-g02-E28","v141-b-g02-E30","v141-b-g02-E31"]},{"parameter_id":"v141-c-R003-theta-epsilon","symbol":"\\varepsilon","meaning":"Very small positive price-adjustment constant added to or subtracted from the DLMP in the modified offer/bid rule.","value":{"kind":"symbolic","number_value":null,"text_value":"very small positive constant, e.g. 10^{-5}; exact value not fixed by the rule"},"unit":"$/p.u.","indices":[],"evidence_ids":["v141-b-g02-E30","v141-b-g02-E31","v141-b-g02-E34"]}],"phi":[{"constraint_id":"v141-c-R003-C001","kind":"procedural","role":"core","statement":"Price-signal coordination provides DLMP feedback to MG supply-offer decisions. Scope: Price-maker MG supply-offer decisions in the decentralized distribution electricity market.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.price_signal","bidding.supply"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E06","v141-b-g01-E08"]},{"constraint_id":"v141-c-R003-C002","kind":"procedural","role":"core","statement":"A microgrid may submit supply offers when it exports power to the DS. Scope: Microgrid supply-offer submission in the distribution electricity market. Condition: The microgrid exports power to the DS.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.supply"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-E26"]},{"constraint_id":"v141-c-R003-C003","kind":"mathematical","role":"core","statement":"Offering-strategy case for an exporting MG with marginal cost below DLMP: if 0 \u003c P_jt \u003c= P_j^max and beta_jt \u003c lambda^P_bt, then the modified supply-offer price is alpha'_jt = lambda^P_bt - epsilon.","expression":"0 \u003c P_{jt} \\le P_j^{\\max} \\;\\land\\; \\beta_{jt} \u003c \\lambda^{P}_{bt} \\;\\Longrightarrow\\; \\alpha'_{jt} = \\lambda^{P}_{bt} - \\varepsilon","formalization_origin":"source","template_id":null,"members":["bidding.supply","coordination.price_signal"],"variable_refs":["v141-c-R003-x-alpha-prime-jt","v141-c-R003-x-P-jt"],"parameter_refs":["v141-c-R003-theta-Pmax-j","v141-c-R003-theta-beta-jt","v141-c-R003-theta-lambda-P-bt","v141-c-R003-theta-epsilon"],"evidence_ids":["v141-b-g02-E28","v141-b-g02-E30"]},{"constraint_id":"v141-c-R003-C004","kind":"mathematical","role":"core","statement":"Offering-strategy case for an exporting MG with marginal cost above DLMP: if 0 \u003c P_jt \u003c= P_j^max and beta_jt > lambda^P_bt, then the modified supply-offer price is alpha'_jt = beta_jt.","expression":"0 \u003c P_{jt} \\le P_j^{\\max} \\;\\land\\; \\beta_{jt} > \\lambda^{P}_{bt} \\;\\Longrightarrow\\; \\alpha'_{jt} = \\beta_{jt}","formalization_origin":"source","template_id":null,"members":["bidding.supply","coordination.price_signal"],"variable_refs":["v141-c-R003-x-alpha-prime-jt","v141-c-R003-x-P-jt"],"parameter_refs":["v141-c-R003-theta-Pmax-j","v141-c-R003-theta-beta-jt","v141-c-R003-theta-lambda-P-bt"],"evidence_ids":["v141-b-g02-E28","v141-b-g02-E31"]},{"constraint_id":"v141-c-R003-C005","kind":"logical","role":"supporting","statement":"Export condition for supply-offer submission: the microgrid exports real power to the DS when P_jt > 0.","expression":"P_{jt} > 0","formalization_origin":"source","template_id":null,"members":["bidding.supply"],"variable_refs":["v141-c-R003-x-P-jt"],"parameter_refs":[],"evidence_ids":["v141-b-g02-E26","v141-b-g02-E30"]}],"pi":[{"evidence_id":"v141-b-g01-E06","location":{"location_id":"src-169a788abb-p03-c1r4__v141-a-M01-bidding","page":3,"printed_page":null,"section":"II. OUTLINE AND ASSUMPTIONS","anchor_text":"y p ( ) , p ator accepts a wide range of management rules beyond the net- tak work operation of DNO ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"The pool bidding [28] and the coordinated management [14] are used together to solve the problem of high penetration levels of MGs in DS. The MGs are strategic players whose bids/offers are subject to market profile, which is decided by nonstrategic players such as the DS customers, DS-owned DGs, and high voltage utility nonstrategic players. The distribution electricity market uses a price signal such as distribution locational marginal price (DLMP) as feedback to MG’s bids/offers. The DLMPs are widely used as price signals among market participants or between the market operator and the market agent [29]."},{"evidence_id":"v141-b-g01-E08","location":{"location_id":"src-169a788abb-p03-c2r2__v141-a-M01-coordination","page":3,"printed_page":null,"section":"II. OUTLINE AND ASSUMPTIONS","anchor_text":"on he ed x- al t- Fig. 1. Decentralized pool strategy for distributed electricity market. t- e- n- a","equation_id":null,"figure_id":"Fig. 1","table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"The microgrid as a price-maker with an independent operator has autonomy to make its own scheduling and bidding/offering decisions in response to distribution system operation states and market price signals which leverage the MGs’ transactive capabilities in the distributed electricity market [29]. As a result, it can help the distribution system operator reduce the decision burden and network complexity."},{"evidence_id":"v141-b-g02-E26","location":{"location_id":"src-169a788abb-p05-c2r4__v141-a-M01-bidding","page":5,"printed_page":null,"section":"D. MG Bidding/Offering Strategy","anchor_text":"1) be solved by using some commercial software packages. The MIP formulation is as follows: min δGit","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"The microgrid is prosumer such that (1) it can submit offers to the distribution market operator when it exports power to the DS or (2) it can submit bids to the distribution market operator when it extracts power from the DS. The bidding/offering prices for MGs in bi-level model always coincide with DLMPs."},{"evidence_id":"v141-b-g01-E03","location":{"location_id":"src-169a788abb-p01-c2r4__v141-a-M01-bidding","page":1,"printed_page":null,"section":"NOMENCLATURE","anchor_text":"Pbt Real power ﬂow at node b in time t. th P(.)t/Q(.)t Real/reactive power output of the MG, DG, uti","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-01.png","occurrence_role":"definition"},"source_text":"Pmax(.)t/Pmin(.)t Maximum/minimum real power output in time t. Qmax(.)t/Qmin(.)t Maximum/minimum reactive power outputs in time t. UR(.)/DR(.) Generator ramp up/down rates. δGit Marginal cost of generation unit i in MG in time t. δLlt Marginal profit of consumer l in DS in time t. δOnt Marginal cost of DG n in DS in time t. δUmt Marginal cost of utility m in time t. O(.) Large positive constant. DPjt/DQjt Real/reactive power consumption for j-th MG in time t. K(.) Incidence matrix. Pbt Real power flow at node b in time t. P(.)t/Q(.)t Real/reactive power output of the MG, DG, utility, consumer in time t. Pinjbt/Qinjbt Real/reactive power injection at node b in time t. Qbt Reactive power flow at node b in time t. Vbt Voltage magnitude at node b in time t. αjt Offering/Bidding price MGj submitted to DS in time t. βjt The j-th MG marginal operation cost in time t. λPbt/λQbt Lagrangian multipliers associated with real/reactive power balance constraints."},{"evidence_id":"v141-b-g02-E15","location":{"location_id":"src-169a788abb-p04-c2r3__v141-a-M01-pricing","page":4,"printed_page":null,"section":"A. Bi-Level Programming Model","anchor_text":"ket. Vmin ≤Vbt ≤Vmax : πminbt , πmaxbt , ∀b ∈B, ∀t} (16) ad. ow The objective function of the upper ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"The DLMPs (\\lambda^{P}_{bt}) are endogenously generated from the lower-level programming model (8)-(16) (LLPM), and the MG uses DLMPs as the base bidding/offering price \\lambda'^{P}_{jt}. The real power and reactive power exchange at PCC belong to the feasible set defined by the LLPM as in constraint (8)."},{"evidence_id":"v141-b-g02-E28","location":{"location_id":"src-169a788abb-p06-c1r2__v141-a-M01-bidding","page":6,"printed_page":null,"section":"D. MG Bidding/Offering Strategy","anchor_text":"ding/offering price (α jt) based on two pieces of price infor T mation: MG corresponding marginal co","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"definition"},"source_text":"To provide a remedy to the issues, we propose a direct and simple bidding/offering strategy for microgrids to find bidding/offering price (\\alpha'_{jt}) based on two pieces of price information: MG corresponding marginal cost (\\beta_{jt}) and DLMPs (\\lambda_{bt}) in DS. The marginal cost of an MG can be obtained at the intersection of the aggregated marginal cost curve of its DGs and the maximum capacity of its PCC. DLMPs are declared at the DS level through the DEM clearing mechanism. Hence, a modified bidding/offering strategy for MGs is proposed as follows:"},{"evidence_id":"v141-b-g02-E30","location":{"location_id":"src-169a788abb-p06-c1r2__v141-a-M01-bidding","page":6,"printed_page":null,"section":"D. MG Bidding/Offering Strategy","anchor_text":"ding/offering price (α jt) based on two pieces of price infor T mation: MG corresponding marginal co","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"condition"},"source_text":"2) If 0\u003cP_{jt}\\le P_j^{\\max} and \\beta_{jt}\u003c\\lambda^{P}_{bt}, it indicates that MG j-th is working on grid connected mode. The MG j-th is transferring power to DS where the market price is relatively higher. Then we set \\alpha'_{jt}=\\lambda^{P}_{bt}-\\varepsilon to make sure DS is willing to take more."},{"evidence_id":"v141-b-g02-E31","location":{"location_id":"src-169a788abb-p06-c1r3__v141-a-M01-bidding","page":6,"printed_page":null,"section":"D. MG Bidding/Offering Strategy","anchor_text":"is willing to take more. 3) If 0 \u003c Pjt ≤P jmax and βjt > λPbt, it indicates that MG j- th is generat","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"condition"},"source_text":"3) If 0\u003cP_{jt}\\le P_j^{\\max} and \\beta_{jt}>\\lambda^{P}_{bt}, it indicates that MG j-th is generating power with higher cost to supply DS loads at a lower price. Then we set \\alpha'_{jt}=\\beta_{jt} to maintain MG's profitability in the market."},{"evidence_id":"v141-b-g02-E34","location":{"location_id":"src-169a788abb-p06-c1r3__v141-a-M01-bidding","page":6,"printed_page":null,"section":"D. MG Bidding/Offering Strategy","anchor_text":"is willing to take more. 3) If 0 \u003c Pjt ≤P jmax and βjt > λPbt, it indicates that MG j- th is generat","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"definition"},"source_text":"It is noted that \\varepsilon is a very small positive constant, e.g., 10^{-5}."},{"evidence_id":"v141-b-g02-E41","location":{"location_id":"src-169a788abb-p08-c1r1__v141-a-M01-bidding","page":8,"printed_page":null,"section":"IV. NUMERICAL EXPERIMENTS","anchor_text":"10 TABLE II EXAMPLE OF MODIFIED MG BIDDING/OFFERING STRATEGY Fi TABLE III COMPARISONS OF MG BIDDING/","equation_id":null,"figure_id":null,"table_id":"Table II","image_ref":"pages/page-08.png","occurrence_role":"example"},"source_text":"TABLE II EXAMPLE OF MODIFIED MG BIDDING/OFFERING STRATEGY. Columns: j, t, \\lambda^{P}_{bt} ($/p.u.), P_{jt} (p.u.), \\alpha_{jt} ($/p.u.), \\beta_{jt} ($/p.u.), \\alpha'_{jt} ($/p.u.). Rows: j=1,t=10, \\lambda^{P}_{bt}=0.44, P_{jt}=-0.024, \\alpha_{jt}=0.44, \\beta_{jt}=0.5, \\alpha'_{jt}=0.44+\\varepsilon; j=2,t=21, \\lambda^{P}_{bt}=0.91, P_{jt}=-0.047, \\alpha_{jt}=0.91, \\beta_{jt}=0.5, \\alpha'_{jt}=0.5; j=2,t=14, \\lambda^{P}_{bt}=0.66, P_{jt}=0.026, \\alpha_{jt}=0.66, \\beta_{jt}=0.5, \\alpha'_{jt}=0.66-\\varepsilon; j=3,t=3, \\lambda^{P}_{bt}=0.44, P_{jt}=0.022, \\alpha_{jt}=0.44, \\beta_{jt}=0.5, \\alpha'_{jt}=0.5."}],"field_notes":{"empty_E_reason":null,"empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-bidding","v141-a-M01-coordination","v141-a-M01-participation","v141-a-M01-pricing"],"extras":{"decision_anchor":"bidding.supply","graph_fact_supports":[[{"evidence_id":"v141-b-g01-E06","quote":"The distribution electricity market uses a price signal such as distribution locational marginal price (DLMP) as feedback to MG’s bids/offers."},{"evidence_id":"v141-b-g01-E08","quote":"The microgrid as a price-maker with an independent operator has autonomy to make its own scheduling and bidding/offering decisions in response to distribution system operation states and market price signals"}],[{"evidence_id":"v141-b-g02-E26","quote":"The microgrid is prosumer such that (1) it can submit offers to the distribution market operator when it exports power to the DS"}]],"C2_formalization":{"graph_sha256":"60e65977c4d6952fb6de35c23db2fa9d2c96f7a9dc42ee17cde24d35bcf23f4c","applicability":"formalized","reason":"Formalized from the source's explicit conditional supply-offer rules for exporting microgrids: when 0 \u003c P_jt \u003c= P_j^max, the modified offer price is set from the DLMP and MG marginal cost depending on whether beta_jt is below or above lambda^P_bt. Existing C001 and C002 are preserved as procedural constraints with unchanged statements, roles, members and original evidence_ids. Added variables and parameters bind to the frozen nodes bidding.supply and coordination.price_signal and to edge v141-c-R003-E001. B evidence remains unreviewed candidate support; this formalization does not claim independent source verification.","bindings":[{"object_id":"v141-c-R003-C001","node_ids":["coordination.price_signal","bidding.supply"],"edge_ids":["v141-c-R003-E001"],"rationale":"Existing procedural price-signal feedback constraint; edge v141-c-R003-E001 is the frozen graph link from coordination.price_signal to bidding.supply."},{"object_id":"v141-c-R003-C002","node_ids":["bidding.supply"],"edge_ids":[],"rationale":"Existing procedural supply-offer permission constraint; it concerns only the bidding.supply node."},{"object_id":"v141-c-R003-C003","node_ids":["bidding.supply","coordination.price_signal"],"edge_ids":["v141-c-R003-E001"],"rationale":"This formal offer-price branch uses the DLMP price signal and sets the MG supply-offer price; it therefore binds to both frozen nodes and the price-signal-to-supply edge."},{"object_id":"v141-c-R003-C004","node_ids":["bidding.supply","coordination.price_signal"],"edge_ids":["v141-c-R003-E001"],"rationale":"This formal offer-price branch compares the MG marginal cost with the DLMP and sets the supply-offer price; it binds to the supply node, price-signal node and E001."},{"object_id":"v141-c-R003-C005","node_ids":["bidding.supply"],"edge_ids":[],"rationale":"The positive-exchange condition P_jt > 0 is the source's export condition for submitting a supply offer; it is attached to bidding.supply."},{"object_id":"v141-c-R003-x-alpha-prime-jt","node_ids":["bidding.supply"],"edge_ids":["v141-c-R003-E001"],"rationale":"The modified offer price is the output of the supply-submission decision and depends on the DLMP price signal through E001."},{"object_id":"v141-c-R003-x-P-jt","node_ids":["bidding.supply"],"edge_ids":[],"rationale":"P_jt is the MG-DS exchange quantity whose positive sign is the source's export condition for a supply offer; no separate exchange node exists in this frozen rule, so it binds to bidding.supply."},{"object_id":"v141-c-R003-theta-Pmax-j","node_ids":["bidding.supply"],"edge_ids":[],"rationale":"P_j^max is the PCC exchange-capacity limit used in the export offer cases and binds to the supply-submission decision node."},{"object_id":"v141-c-R003-theta-beta-jt","node_ids":["bidding.supply"],"edge_ids":[],"rationale":"The MG marginal operation cost is an input to the supply-offer rule and binds to bidding.supply."},{"object_id":"v141-c-R003-theta-lambda-P-bt","node_ids":["coordination.price_signal"],"edge_ids":["v141-c-R003-E001"],"rationale":"The DLMP is the price signal represented by coordination.price_signal and is connected to supply submission by E001."},{"object_id":"v141-c-R003-theta-epsilon","node_ids":["bidding.supply"],"edge_ids":[],"rationale":"The small price-adjustment constant is used directly in the supply-offer price rule and binds to bidding.supply."}],"revision_requests":[]}},"quarantined_references":[]}});
